const $=s=>document.querySelector(s);
const lessons=[
{title:'Start from zero',nav:'Start a repository',description:'Create your first Git repository and saved recipe.',duration:5,steps:[['Start Git tracking','git init -b main','git init -b main'],['Write your first recipe','Create pancakes.txt','edit pancakes.txt'],['Choose what to save','git add pancakes.txt','git add pancakes.txt'],['Create your first save','git commit -m "Start pancake recipe"','git commit -m "Start pancake recipe"']],insight:['Start local','Initialize → edit → stage → commit → connect → push.'],hint:'Your first commit will appear when you save the staged recipe.'},
{title:'A parallel universe',nav:'Branches & merging',description:'Try an idea on its own branch, then bring it back into main.',duration:4,steps:[['Create a branch','git switch -c feature','git switch -c feature'],['Build your idea','Edit, stage & commit','build-feature'],['Return to main','git switch main','git switch main'],['Bring it together','git merge feature','git merge feature']],insight:['A branch is a pointer','Branches share history. They don’t copy an entire project. HEAD tracks the branch you are working on.'],hint:'Make space for an idea without disturbing main.'},
{title:'Local meets remote',nav:'GitHub & remotes',description:'Your machine and GitHub have separate copies. Keep them in sync deliberately.',duration:6,steps:[['Connect your GitHub repository','git remote add origin <url>','git remote add origin https://github.com/you/pancake-project.git'],['Upload your saved recipe','git push -u origin main','git push -u origin main'],['Edit your recipe on GitHub','Save a change in the online editor','remote-change'],['Download the new history','git fetch origin','git fetch origin'],['Update your computer’s copy','git merge origin/main','git merge origin/main'],['Publish your next improvement','Edit, stage, commit & push','publish-change']],insight:['Fetch ≠ pull','Fetch downloads history and updates origin/main. Pull fetches, then integrates using merge or rebase.'],hint:'Git works locally. GitHub hosts a remote repository.'},
{title:'Better, together',nav:'Team collaboration',description:'You, Maya, and Leo share one project. Propose a feature, review it, and merge it.',duration:6,steps:[['Get the team’s repository','git clone <url>','git clone https://github.com/team/pancake-project.git'],['Start your feature','git switch -c feature','git switch -c feature'],['Push your work','Commit & publish branch','team-push'],['Open a pull request','Propose feature → main','open-pr'],['Get a teammate’s review','Maya approves the change','review-pr'],['Merge on GitHub','A merge commit joins histories','merge-pr'],['Update your local copy','git pull --ff-only origin main','team-pull']],insight:['People behind the pointers','A pull request is a GitHub conversation about a proposed change. Reviews help a team decide what to merge.'],hint:'Each person has their own local repository. GitHub is the shared meeting point.'},
{title:'Two edits. One decision.',nav:'Merge conflicts',description:'You and Maya changed the same line. Decide what the finished file should say.',duration:4,steps:[['Try to merge','git merge feature','git merge feature'],['Resolve the line','Choose a result below the graph','resolve-conflict'],['Stage the resolved file','git add pancakes.txt','git add pancakes.txt'],['Finish the merge','git commit','git commit -m "Agree on sugar amount"']],insight:['Conflicts are a conversation','Git asks for a decision when it cannot combine changes automatically. Resolve the file, stage it, then commit.'],hint:'Both histories are safe. Choose the final content before finishing the merge.'},
{title:'A safe way back',nav:'Undo & recovery',description:'Undo a published mistake while keeping the shared history intact.',duration:3,steps:[['Inspect the latest change','git show HEAD','git show HEAD'],['Undo with a new commit','git revert HEAD','git revert HEAD'],['Share the correction','git push origin main','git push origin main']],insight:['Undo without erasing','Revert adds an inverse commit. Reset moves a branch pointer; --hard can discard local work. Prefer revert for shared commits.'],hint:'A revert preserves the original commit and records a correction.'}
];
const editRecipeStep=['Edit the recipe','Add chocolate chips to pancakes.txt','edit pancakes.txt'],stageRecipeStep=['Select the changed recipe','git add pancakes.txt','git add pancakes.txt'],saveRecipeStep=['Save the chocolate variation','git commit -m "Add chocolate chips"','git commit -m "Add chocolate chips"'];
lessons[1].steps.splice(1,1,[...editRecipeStep],[...stageRecipeStep],[...saveRecipeStep]);
lessons[2].steps.splice(5,1,['Improve the cooking instructions','Edit pancakes.txt','edit pancakes.txt'],[...stageRecipeStep],['Save the improved instructions','git commit -m "Clarify pancake instructions"','git commit -m "Clarify pancake instructions"'],['Upload the saved improvement','git push origin main','git push origin main']);
lessons[3].steps.splice(2,1,[...editRecipeStep],[...stageRecipeStep],[...saveRecipeStep],['Send feature to GitHub','git push -u origin feature','git push -u origin feature']);
lessons.forEach((item,i)=>{const guide=beginnerGuides[i];Object.assign(item,{title:guide.title,description:guide.description,insight:guide.insight,hint:guide.hint});item.steps.forEach((step,j)=>{step[0]=guide.steps[j][0];step[1]=guide.steps[j][1]});});
const learningPaths={solo:{name:'Solo path',ids:[0,1,2,5],description:'Your computer → your own GitHub repository. Learn one person’s workflow first.'},team:{name:'Team path',ids:[3,4],description:'Join an existing project → propose changes → review → resolve conflicts.'}};
function pathFor(id){return [3,4].includes(id)?'team':'solo'}
function pathPosition(){return learningPaths[mode].ids.indexOf(lesson)+1}
function nextPathLesson(){const ids=learningPaths[pathFor(lesson)].ids;return ids[ids.indexOf(lesson)+1]}
function continuationLabel(){return nextPathLesson()!==undefined?'Continue to next lesson':mode==='solo'?'Solo path complete · return to paths':'Team path complete · return to paths'}
let lesson=0,step=0,mode='solo',view='introduction',playing=false,timer=null,commandHistory=[],historyIndex=0;let completed=[];try{completed=JSON.parse(localStorage.getItem('git-orbit-completed')||'[]');if(!Array.isArray(completed))completed=[]}catch{}let state;
const classicRecipe=['# Pancake recipe','Flour: 1 cup','Milk: 1 cup','Sugar: 1 tablespoon','Chocolate chips: none','','Mix flour, milk, and sugar.','Cook until golden.'].join('\n');
function recipeAt(id){return state?.commits.find(c=>c.id===id)?.content??null}
function updateRecipeLine(content,prefix,line){return content.split('\n').map(text=>text.startsWith(prefix)?line:text).join('\n')}
function combineRecipe(a,b,base=classicRecipe){const left=(a||base).split('\n'),right=(b||base).split('\n');return base.split('\n').map((line,i)=>right[i]!==line?right[i]:left[i]).join('\n')}
function makeCommit(id,message,parent=null,branch='main',author='You',content=classicRecipe){return{id,message,parent,branch,author,content}}
function initialState(){const fresh=lesson===0,joining=lesson===3,connected=[3,4,5].includes(lesson);return{initialized:!fresh&&!joining,remoteConfigured:connected&&!joining,branch:'main',commits:fresh?[]:[makeCommit('a1c9e2','Start pancake recipe',null,'main',joining?'Maya':'You')],main:fresh||joining?null:'a1c9e2',feature:null,remote:connected?'a1c9e2':null,tracking:connected&&!joining?'a1c9e2':null,working:null,staged:null,revision:0,pr:null,conflict:false,resolved:false,reverted:false,file:null,stagedFile:null,fileTab:'working',fileNotice:'Follow the lesson to watch this file change.'}}
function resetLesson(){stopTour();$('.lesson-outline').open=true;step=0;resetLessonQuiz();state=initialState();if(lesson===4){state.feature='e9a2f5';state.main='d6c1b2';state.commits.push(makeCommit('d6c1b2','Your recipe: 1 tablespoon of sugar','a1c9e2','main'),makeCommit('e9a2f5','Maya’s recipe: 2 tablespoons of sugar','a1c9e2','feature','Maya'));state.remote=state.main;state.tracking=state.main}if(lesson===5){state.commits.push(makeCommit('d6c1b2','Accidentally remove flour','a1c9e2'));state.main=state.remote=state.tracking='d6c1b2'}if(lesson===4){state.commits.find(c=>c.id===state.feature).content=updateRecipeLine(classicRecipe,'Sugar:','Sugar: 2 tablespoons');}if(lesson===5){state.commits.find(c=>c.id===state.main).content=classicRecipe.split('\n').filter(line=>!line.startsWith('Flour:')).join('\n');}state.file=state.initialized?recipeAt(state[state.branch]):null;$('#terminal-output').innerHTML='<div class="terminal-welcome"><span>✦</span> A fresh sandbox. Try a quick command or follow the lesson.</div>';render();}
function selectLesson(i){lesson=i;mode=pathFor(i);view='lab';resetLesson();renderView();window.scrollTo({top:0,behavior:'auto'})}
function renderNav(){ $('#lesson-nav').innerHTML=Object.entries(learningPaths).map(([key,path])=>`<div class="path-nav-heading ${mode===key?'selected':''}"><span>${key==='solo'?'01 · LEARN SOLO FIRST':'02 · WORK AS A TEAM'}</span><small>${path.ids.filter(id=>completed.includes(id)).length} / ${path.ids.length}</small></div>${path.ids.map((id,index)=>`<button data-lesson="${id}" class="${id===lesson&&view==='lab'?'active':''} ${completed.includes(id)?'done':''}"><span class="number">${completed.includes(id)?'✓':String(index+1).padStart(2,'0')}</span>${lessons[id].nav}${id===lesson&&view==='lab'?'<span class="lesson-active"></span>':''}</button>`).join('')}`).join('');const ids=learningPaths[mode].ids,count=ids.filter(id=>completed.includes(id)).length;$('#overall-progress').textContent=`${count} / ${ids.length}`;$('.progress-head>span:first-child').textContent=learningPaths[mode].name+' progress';$('#overall-bar').style.width=`${count/ids.length*100}%`;document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-selected',String(b.dataset.mode===mode))})}
function render(){renderNav();const l=lessons[lesson];$('#lesson-number').textContent=`${mode.toUpperCase()} ${String(pathPosition()).padStart(2,'0')} / ${String(learningPaths[mode].ids.length).padStart(2,'0')}`;$('#lesson-duration').textContent=`~ ${l.duration} MIN`;$('#lesson-title').textContent=l.title;$('#lesson-description').textContent=l.description;$('#outline-count').textContent=`${l.steps.length} steps`;$('#guide-steps').innerHTML=l.steps.map((s,i)=>`<div class="guide-step ${i<step?'done':i===step?'current':''}"><span class="step-circle">${i<step?'✓':i+1}</span><div><strong>${s[0]}</strong><small>${s[1]}</small></div></div>`).join('');$('#insight-title').textContent=l.insight[0];$('#insight-text').textContent=l.insight[1];$('#next-action').innerHTML=step>=l.steps.length?'Continue to next lesson <span>✦</span>':`${l.steps[step][0]} <span>⌘</span>`;$('#lesson-step-label').textContent=step>=l.steps.length?'Lesson complete':`Step ${step+1} of ${l.steps.length}`;$('#step-dots').innerHTML=l.steps.map((_,i)=>`<i class="${i<=step?'active':''}"></i>`).join('');$('.guide-panel').classList.toggle('completed',step>=l.steps.length);$('#visual-hint').textContent=lesson===0?(state.commits.length?'You made this circle yourself: your first saved recipe.':state.initialized?'Git is ready. No commits yet: edit, stage, then save.':'An ordinary empty folder. Start Git tracking to begin.'):l.hint;$('#terminal-branch').textContent=state.initialized?`(${state.branch})`:'(folder)';$('#head-status').innerHTML=state.initialized?`<i></i> Working on <code>${state.branch}</code> · ${state.main?'HEAD':'no commits yet'}`:lesson===3?'<i></i> Shared project · clone it to your computer':'<i></i> Ordinary folder · Git tracking has not started';$('#graph-title').textContent=!state.initialized?(lesson===3?'The team’s repository on GitHub':'Your empty project folder'):mode==='team'?'One project. Three perspectives.':'Your repository, visualized';$('.graph-legend').hidden=!state.commits.length;$('.graph-status>span:last-child').textContent=state.commits.length?'Click a commit to inspect':'No commits to inspect yet';$('#graph-location').textContent=!state.initialized?(lesson===3?'GITHUB · NOT CLONED YET':'PROJECT FOLDER'):[2,3].includes(lesson)||lesson===0&&state.remote?'LOCAL + GITHUB':state.remoteConfigured?'LOCAL + GITHUB':'LOCAL REPOSITORY';renderGraph();renderZones();renderFileWorkbench();renderChips();renderBeginnerGuide();renderLessonQuiz();}
function renderGraph(){const commits=state.commits;if(!commits.length){$('#graph').innerHTML=`<div class="empty-history"><span class="section-kicker">${state.initialized?'REPOSITORY READY · 0 COMMITS':'STARTING POINT · EMPTY FOLDER'}</span><h3>${state.initialized?'Git is ready. Your history is empty.':'Every project starts here.'}</h3><p>${state.initialized?'Creating and staging a file will not add a circle. Your first commit will.':'No files. No saved versions. No GitHub connection. Run git init to begin tracking this folder.'}</p><div class="setup-status"><span class="${state.initialized?'ready':''}">${state.initialized?'✓':'1'} Git tracking</span><span class="${state.working?'ready':''}">${state.working?'✓':'2'} Recipe file</span><span class="${state.staged?'ready':''}">${state.staged?'✓':'3'} Staged</span><span>4 First commit</span></div></div>`;return}const positions=new Map();const hasFeature=commits.some(c=>c.branch==='feature');const isRemote=!!state.remote&&([2,3,5].includes(lesson)||state.remoteConfigured);let mainIndex=0,featureIndex=0,remoteIndex=0;commits.forEach(c=>{if(c.branch==='main'){positions.set(c.id,{x:78+mainIndex*92,y:hasFeature?101:121});mainIndex++}else if(c.branch==='feature'){positions.set(c.id,{x:265+featureIndex*92,y:180});featureIndex++}else{positions.set(c.id,{x:365+remoteIndex*92,y:65});remoteIndex++}});const references=[{id:state.main,text:'main',color:'#63e9c3'},{id:state.feature,text:'feature',color:'#bba2fa'}];if(isRemote){references.push({id:state.remote,text:'GitHub',color:'#75b9ff'});if(state.tracking!==state.remote)references.push({id:state.tracking,text:'origin/main',color:'#75b9ff'})}const visibleReferences=references.filter(ref=>positions.has(ref.id)),referenceCounts=new Map();visibleReferences.forEach(ref=>referenceCounts.set(ref.id,(referenceCounts.get(ref.id)||0)+1));positions.forEach((p,id)=>{const count=referenceCounts.get(id)||0;if(count)p.y=Math.max(p.y,(mode==='team'?50:12)+42+(count-1)*29)});const width=Math.max(580,mainIndex*92+160),height=Math.max(236,...[...positions.values()].map(p=>p.y+68));const color=c=>c.branch==='feature'?'#bba2fa':c.branch==='remote'?'#75b9ff':'#63e9c3';let paths='';commits.forEach(c=>{const p=positions.get(c.id),parents=Array.isArray(c.parent)?c.parent:[c.parent];parents.filter(Boolean).forEach(pid=>{const prev=positions.get(pid);if(prev)paths+=`<path class="graph-edge" d="M${prev.x} ${prev.y} C${prev.x+45} ${prev.y} ${p.x-45} ${p.y} ${p.x} ${p.y}" fill="none" stroke="${color(c)}" stroke-width="2" opacity=".65"/>`})});let nodes=commits.map((c,i)=>{const p=positions.get(c.id);return`<g class="commit-node ${i===commits.length-1?'new-node':''}" data-commit="${c.id}" tabindex="0" role="button" aria-label="Inspect commit ${escapeHTML(c.message)}"><title>${escapeHTML(c.message)}</title><circle class="node-ring" cx="${p.x}" cy="${p.y}" r="17" fill="${color(c)}" opacity=".2"/><circle class="node-core" cx="${p.x}" cy="${p.y}" r="8" fill="#0f151d" stroke="${color(c)}" stroke-width="2"/><circle cx="${p.x}" cy="${p.y}" r="2.5" fill="${color(c)}"/><text x="${p.x}" y="${p.y+32}" text-anchor="middle" fill="#6d889c" font-size="10">Save ${i+1}</text></g>`}).join('');// Allocate a unique label slot for every reference to the same commit.
const labelSlots=new Map();const label=ref=>{const p=positions.get(ref.id),offset=(labelSlots.get(ref.id)||0)*29;labelSlots.set(ref.id,(labelSlots.get(ref.id)||0)+1);return `<g class="branch-label" data-reference="${ref.text}" data-points-to="${ref.id}" transform="translate(${p.x-30},${p.y-42-offset})"><title>${ref.text} points to ${ref.id}</title><rect width="${ref.text.length*6.5+18}" height="21" rx="4" fill="${ref.color}18" stroke="${ref.color}65"/><text x="9" y="14" fill="${ref.color}" font-size="10">${ref.text}</text></g>`};let labels=visibleReferences.map(label).join('');const head=positions.get(state[state.branch]);if(head)labels+=`<text x="${head.x}" y="${head.y+54}" fill="#c1d4e2" font-size="9" text-anchor="middle">YOU ARE HERE ↓</text>`;let team=mode==='team'?'<div class="team-labels"><span class="team-person"><b>Y</b> You · developer</span><span class="team-person"><b>M</b> Maya · reviewer</span><span class="team-person"><b>L</b> Leo · teammate</span></div>':'';$('#graph').innerHTML=team+`<svg viewBox="0 0 ${width} ${height}" role="group" aria-label="Commit history. Main points to ${state.main}${state.feature?', feature points to '+state.feature:''}">${paths}${nodes}${labels}</svg>`;}
function renderZones(){let zones=[['▱','Working directory',state.working?'pancakes.txt':null,state.main?'Tracked recipe · no edits':state.initialized?'No files yet':'Empty project folder'],['◫','Staging area',state.staged?'pancakes.txt':null,'Your next snapshot'],['⑂','Repository',state[state.branch],state.initialized?'No commits yet':'Run git init first']];if(lesson===3&&!state.initialized)zones=[['▱','Your computer',null,'No local copy yet'],['↓','Next action',null,'Clone the existing project'],['⑂','GitHub repository',state.remote,'Maya’s existing recipe']];if(lesson===4){zones[0][2]=state.working?'pancakes.txt':null;zones[1][2]=state.staged?'pancakes.txt':null}if(lesson===3&&state.pr)zones=[['♧','Pull request',`feature → main`,state.pr],['◫','Review',state.pr==='approved'||state.pr==='merged'?'Maya approved':null,'Waiting for Maya'],['⑂','GitHub main',state.remote,'Shared with your team']];$('#file-zones').innerHTML=zones.map((z,i)=>`<div class="file-zone ${z[2]?'active':''}"><div class="zone-title"><b>${z[0]}</b>${z[1]}<span class="zone-count">${i===2?state.commits.length:z[2]?1:0}</span></div><div class="${z[2]?'zone-file':'zone-empty'}">${z[2]||z[3]}${z[2]?'<em>'+ (i===2?'✓':i===1?'A':'M')+'</em>':''}</div></div>`).join('');const old=$('.conflict-editor');if(old)old.remove();if(lesson===4&&state.conflict){const e=document.createElement('div');e.className='conflict-editor';e.innerHTML=`<p>pancakes.txt · Choose the sugar amount, then stage the file.</p><pre>${state.resolved?`${state.resolution}`:'<<<<<<< HEAD\nSugar: 1 tablespoon\n=======\nSugar: 2 tablespoons\n>>>>>>> feature'}</pre><div class="conflict-options"><button data-resolve="Sugar: 1 tablespoon">Keep yours · 1 tablespoon</button><button data-resolve="Sugar: 2 tablespoons">Keep Maya’s · 2 tablespoons</button><button data-resolve="Sugar: 1.5 tablespoons">Agree on · 1.5 tablespoons</button></div>`;$('#file-zones').after(e)}}
function editedRecipe(){let content=state.file??classicRecipe;if(!state[state.branch]&&state.revision===1)return classicRecipe;if(state.branch==='feature'){const chips=content.includes('Chocolate chips: 2 tablespoons')?'Chocolate chips: 3 tablespoons':'Chocolate chips: 2 tablespoons';return updateRecipeLine(content,'Chocolate chips:',chips)}if(content.includes('Cook until golden.'))return updateRecipeLine(content,'Cook ','Cook on medium heat until golden.');if(content.includes('Milk: 1 cup'))return updateRecipeLine(content,'Milk:','Milk: 1.25 cups');return updateRecipeLine(content,'Cook ',content.includes('Cook for 2 minutes on each side.')?'Cook for 3 minutes on each side.':'Cook for 2 minutes on each side.')}
function revealRecipe(){requestAnimationFrame(()=>{const target=innerWidth<=650?$('#file-workbench .current-file'):$('#file-workbench');target?.scrollIntoView({behavior:document.body.classList.contains('motion-paused')||matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'})})}
function fileDifference(before,after){const a=(before??'').split('\n'),b=(after??'').split('\n');if(before===null)a.length=0;if(after===null)b.length=0;const table=Array.from({length:a.length+1},()=>Array(b.length+1).fill(0));for(let i=a.length-1;i>=0;i--)for(let j=b.length-1;j>=0;j--)table[i][j]=a[i]===b[j]?table[i+1][j+1]+1:Math.max(table[i+1][j],table[i][j+1]);let i=0,j=0,left=[],right=[];while(i<a.length||j<b.length){if(i<a.length&&j<b.length&&a[i]===b[j]){left.push({text:a[i],number:++i,kind:''});right.push({text:b[j],number:++j,kind:''})}else if(j<b.length&&(i===a.length||table[i][j+1]>=table[i+1][j])){right.push({text:b[j],number:++j,kind:'added'})}else{left.push({text:a[i],number:++i,kind:'removed'})}}return{left,right,added:right.filter(l=>l.kind).length,removed:left.filter(l=>l.kind).length}}
function recipeLines(lines,empty){return lines.length?lines.map(line=>`<div class="recipe-code-line ${line.kind}"><span class="recipe-line-number">${line.number}</span><span class="recipe-line-mark" aria-label="${line.kind==='added'?'Added line':line.kind==='removed'?'Removed line':'Unchanged line'}">${line.kind==='added'?'+':line.kind==='removed'?'−':''}</span><code>${escapeHTML(line.text)||'&nbsp;'}</code></div>`).join(''):`<p class="recipe-file-empty">${empty}</p>`}
function renderFileWorkbench(){const tab=state.fileTab,saved=recipeAt(state[state.branch]),shown=tab==='staged'?state.stagedFile:tab==='github'?recipeAt(state.remote):state.file,diff=shown===null?{left:fileDifference(saved,saved).left,right:[],added:0,removed:0}:fileDifference(saved,shown);const titles={working:'Working file · your computer',staged:'Selected for the next commit',github:'Online file · GitHub main'};const empty=tab==='staged'?'Nothing staged. Editing a file and selecting it are separate actions.':tab==='github'?'No uploaded recipe yet. Connect your repository and push a saved commit.':lesson===3?'Clone the project to bring this recipe onto your computer.':'pancakes.txt does not exist yet. Write your first recipe to create it.';$('#file-workbench').innerHTML=`<div class="file-workbench-head"><div><span class="section-kicker">SEE THE FILE CHANGE</span><h3><span>▤</span> pancakes.txt</h3></div><span class="file-change-count">${diff.added||diff.removed?`<b>+${diff.added}</b> <em>−${diff.removed}</em>`:shown===null?'NO CONTENT YET':'CONTENTS MATCH'}</span></div><div class="file-copy-tabs" role="tablist" aria-label="Recipe copy"><button role="tab" aria-selected="${tab==='working'}" data-file-tab="working">Working file ${state.working?'<i></i>':''}</button><button role="tab" aria-selected="${tab==='staged'}" data-file-tab="staged">Staging area ${state.staged?'<i></i>':''}</button>${state.remoteConfigured?`<button role="tab" aria-selected="${tab==='github'}" data-file-tab="github">GitHub copy</button>`:''}</div><div class="recipe-code-panes"><section><div class="recipe-code-label"><strong>LAST SAVED ON ${state.branch.toUpperCase()}</strong><small>${state[state.branch]??'No commits yet'}</small></div><div class="recipe-code">${recipeLines(diff.left,'No saved file yet. Init and staging do not create a saved version.')}</div></section><section class="current-file"><div class="recipe-code-label"><strong>${titles[tab]}</strong><small>${tab==='working'?(state.working?'Edited · not committed':shown?'Saved contents':'No file yet'):tab==='staged'?(state.staged?'Ready to commit':'Nothing selected'):shown?'Saved online':'Not uploaded'}</small></div><div class="recipe-code">${recipeLines(diff.right,empty)}</div></section></div><p class="recipe-file-notice" role="status"><span>✦</span>${escapeHTML(tab==='staged'&&!state.staged?'Nothing is selected for a commit. Your working edits still exist; staging chooses the contents to save.':state.fileNotice)}</p><div class="recipe-diff-key"><span><i class="added"></i> Green +: added or changed content</span><span><i class="removed"></i> Red −: replaced or removed content</span></div>`;}
function renderChips(){const sets=[['git init -b main','edit pancakes.txt','git status','git add pancakes.txt','git commit -m "Start pancake recipe"'],['git switch -c feature','git status','git switch main','git merge feature'],['git remote add origin https://github.com/you/pancake-project.git','git push -u origin main','git fetch origin','git status','git merge origin/main'],['git clone https://github.com/team/pancake-project.git','git switch -c feature','git status','git log --oneline','git pull --ff-only origin main'],['git merge feature','git status','git add pancakes.txt','git commit -m "Agree on sugar amount"'],['git show HEAD','git revert HEAD','git log --oneline','git push origin main']];$('#command-chips').innerHTML=sets[lesson].map(c=>`<button data-command="${c.replaceAll('"','&quot;')}">${c}</button>`).join('')}
function log(message,type='info'){const line=document.createElement('div');line.className=`terminal-line ${type}`;line.textContent=message;$('#terminal-output').append(line);$('#terminal-output').scrollTop=$('#terminal-output').scrollHeight;}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function advance(){step++;if(step===lessons[lesson].steps.length){if(!completed.includes(lesson)){completed.push(lesson);try{localStorage.setItem('git-orbit-completed',JSON.stringify(completed))}catch{}}toast('Practice complete. Try the two-question recap below.')}render();if(step===lessons[lesson].steps.length)focusLessonQuiz()}
function addCommit(message,branch=state.branch,parents=state[branch],author='You'){const id=['a1c9e2','b7f3d1','c4e8a6','d6c1b2','e9a2f5','f3b7d8','19c4e6','28d5f1','37e6a2','46f7b3','55a8c4'].find(id=>!state.commits.some(c=>c.id===id))||`${state.commits.length}ab7c1`;const parentIds=Array.isArray(parents)?parents:[parents];const content=state.commitContent!==undefined?state.commitContent:branch==='remote'?combineRecipe(recipeAt(parentIds[0]),recipeAt(parentIds[1])):state.stagedFile??state.file??classicRecipe;delete state.commitContent;const c=makeCommit(id,message,parents,branch,author,content);state.commits.push(c);if(branch==='remote')state.remote=id;else state[branch]=id;return id}
function applyStageProgress(event){const expected=lessons[lesson].steps[step]?.[2];const expectedEvent=expected?.startsWith('edit')?'edit':expected?.startsWith('git add')?'add':expected?.startsWith('git commit')?'commit':expected?.startsWith('git push')?'push':expected?.startsWith('git remote add')?'connect-remote':expected;if(event===expectedEvent)advance();else render()}
function execute(raw){const command=raw.trim();if(!command)return;log(`❯ ${command}`,'command');commandHistory.push(command);historyIndex=commandHistory.length;const cmd=command.replace(/\s+/g,' ');try{
if(cmd==='help'){log('Supported: git init -b main · git clone <url> · git remote add origin <url> · edit pancakes.txt · git status · git add <file> · git commit -m "message" · git switch -c feature · git switch main · git merge feature · git fetch origin · git merge origin/main · git pull --ff-only origin main · git push origin <branch> · git log --oneline · git show HEAD · git revert HEAD · clear');return}
if(cmd==='clear'){$('#terminal-output').innerHTML='';return}
if(cmd==='git init'||cmd==='git init -b main'){if(lesson===3&&!state.initialized)throw Error('This team project already has history on GitHub. Use git clone to download it.');if(state.initialized){log('Git tracking is already initialized. No commits were added.');return}state.initialized=true;log('Initialized an empty Git repository in pancake-project/.git/. Initial branch: main. No commits yet.','success');if(step===0&&lesson===0)advance();return}
if(/^git clone https:\/\/github\.com\/[\w.-]+\/[\w.-]+(?:\.git)?$/.test(cmd)){if(lesson!==3)throw Error('Open the Team path to practice joining an existing project. Use init for your own new folder.');if(state.initialized){log('You already have the team’s local copy.');return}state.initialized=true;state.remoteConfigured=true;state.main=state.tracking=state.remote;state.file=recipeAt(state.main);state.fileNotice='Cloning brought this existing recipe file to your computer.';log('Cloned the team’s files and history to your computer. origin is configured automatically. No new commit was created.','success');applyStageProgress(lessons[lesson].steps[0][2]);return}
if(!state.initialized)throw Error(lesson===3?'Download the existing team repository with git clone first.':'This folder is not a Git repository yet. Start with git init -b main.');
if(/^git remote add origin https:\/\/github\.com\/[\w.-]+\/[\w.-]+(?:\.git)?$/.test(cmd)){if(state.remoteConfigured)throw Error('origin is already connected in this sandbox.');state.remoteConfigured=true;log('Connected origin to the empty example GitHub repository. No files uploaded. This lab simulates creating the remote; it does not create a real GitHub repository.','success');applyStageProgress('connect-remote');return}
if(cmd==='git remote -v'){log(state.remoteConfigured?'origin https://github.com/you/pancake-project.git (fetch / push)':'No remotes configured.');return}
if(cmd==='git status'){log(`On branch ${state.branch}${state.main?'':'\nNo commits yet'}\n${state.conflict&&!state.resolved?'Unmerged paths: pancakes.txt (both modified)':state.staged?'Changes to be committed: '+'pancakes.txt':state.working?(state.main?'Changes not staged for commit: pancakes.txt':'Untracked file: pancakes.txt'):(state.main?'Nothing to commit, working tree clean':'No files yet')}${!state.remoteConfigured?'\nNo GitHub remote connected.':state.main!==state.remote?'\nLocal main and GitHub main point to different snapshots.':''}`);return}
if(cmd==='git log'||cmd==='git log --oneline'){if(!state.main)throw Error('No commits yet. Create your first commit to start the history.');let id=state[state.branch],chain=[],seen=new Set;while(id&&!seen.has(id)){seen.add(id);const c=state.commits.find(c=>c.id===id);if(!c)break;chain.push(`${c.id} ${c.message}`);id=Array.isArray(c.parent)?c.parent[0]:c.parent}log(chain.join('\n'));return}
if(cmd==='git show HEAD'){if(!state[state.branch])throw Error('No saved version yet. Create your first commit before inspecting HEAD.');const c=state.commits.find(c=>c.id===state[state.branch]);log(`${c.id} · ${c.message}\nAuthor: ${c.author}\n${lesson===5?'− Flour: 1 cup':'A saved snapshot of the pancake recipe.'}`);if(lesson===5&&step===0)advance();return}
if(/^edit (pancakes\.txt)$/.test(cmd)){if(state.conflict)throw Error('Resolve the conflict using the choices below the graph.');state.working=++state.revision;state.file=editedRecipe();state.fileTab='working';state.fileNotice=state.main?'The highlighted lines changed in your working file. The saved version stays the same.':'You created pancakes.txt. These new lines are not staged or saved yet.';log(state.main?'Edited pancakes.txt. The saved history has not changed.':'Created pancakes.txt with a classic pancake recipe. It is untracked and not saved as a commit yet.','success');applyStageProgress('edit');revealRecipe();return}
if(/^git add (pancakes\.txt|\.)$/.test(cmd)){if(state.conflict&&!state.resolved)throw Error('Choose the final sugar amount before staging the resolution.');if(!state.working)throw Error('No edited file to stage. Run edit pancakes.txt first.');state.staged=state.working;state.stagedFile=state.file;state.fileTab='staged';state.fileNotice='Staging copied these exact contents into the next snapshot. Your saved commit has not changed.';log('Staged the current file content for the next snapshot.','success');applyStageProgress('add');return}
if(/^git commit(?: -m (?:"[^"]+"|'[^']+'|\S+))?$/.test(cmd)){if(!state.staged)throw Error('Nothing staged. Edit a file and run git add first.');const msg=cmd.match(/-m ["']?(.*?)["']?$/)?.[1]||'Save changes';const parents=state.conflict?[state.main,state.feature]:state[state.branch];addCommit(msg,state.branch,parents);state.working=state.working===state.staged?null:state.working;state.staged=null;state.stagedFile=null;state.fileTab='working';state.conflict=false;state.fileNotice=state.working?'Commit saved the previously staged contents. Your later edit is still highlighted because it was not selected for this save.':'Commit saved the selected contents. Your working file and saved version now match.';log(`Saved snapshot ${state[state.branch]}. Your commit exists locally.`, 'success');applyStageProgress('commit');return}
if(cmd==='git switch -c feature'){if(!state[state.branch])throw Error('Create your first commit before starting a feature branch in this sandbox.');if(state.feature)throw Error('Branch feature already exists. Use git switch feature.');if(state.working||state.staged)throw Error('Finish the current change before starting this lesson’s feature branch.');state.feature=state[state.branch];state.branch='feature';log('Created feature at the current commit and switched HEAD to it.','success');applyStageProgress(cmd);return}
if(cmd==='git switch main'||cmd==='git switch feature'){if(state.conflict)throw Error('Resolve or finish the merge before switching.');if(state.working||state.staged)throw Error('Commit your current changes before switching in this sandbox.');const b=cmd.split(' ')[2];if(!state[b])throw Error(`Branch ${b} does not exist. Create it with git switch -c feature.`);state.branch=b;state.file=recipeAt(state[b]);state.fileTab='working';state.fileNotice=`Switching to ${b} shows that branch’s saved recipe.`;log(`Switched to ${b}. HEAD follows ${b}.`,'success');applyStageProgress(cmd);return}
if(cmd==='git merge feature'){if(state.branch!=='main')throw Error('Switch to main before merging feature.');if(!state.feature)throw Error('Create and commit on feature first.');if(state.conflict)throw Error('A merge is already in progress. Resolve, stage, and commit.');if(lesson===4&&!state.resolved){state.conflict=true;state.working='conflict';state.file=updateRecipeLine(state.file,'Sugar:','<<<<<<< HEAD\nSugar: 1 tablespoon\n=======\nSugar: 2 tablespoons\n>>>>>>> feature');state.fileNotice='The file contains conflict markers. Choose the sugar amount below to replace them.';log('CONFLICT: both branches changed pancakes.txt. Git paused the merge. Choose a result below the graph.','error');applyStageProgress(cmd);return}if(state.main===state.feature){log('Already up to date.');return}const feature=state.commits.find(c=>c.id===state.feature);if(feature.parent===state.main){state.main=state.feature;log('Fast-forward: main moved to the feature snapshot. No merge commit was needed.','success')}else{addCommit('Merge feature','main',[state.main,state.feature]);log('Created a merge commit with two parents.','success')}state.file=recipeAt(state.main);state.fileNotice='Merging brings the saved variation into your main recipe.';applyStageProgress(cmd);return}
if(cmd==='git fetch origin'){if(!state.remoteConfigured)throw Error('Connect a remote with git remote add origin <url> first.');state.tracking=state.remote;state.fileNotice='Fetch downloaded online history. Your working recipe remains unchanged; open the GitHub copy tab to compare.';log('Downloaded remote history. origin/main now points to GitHub main; your local main did not move.','success');applyStageProgress(cmd);return}
if(cmd==='git merge origin/main'){if(state.branch!=='main')throw Error('Switch to main for this lesson.');if(state.tracking===state.main){log('Already up to date. Run git fetch origin to discover remote updates.');return}if(!isAncestor(state.main,state.tracking))throw Error('Histories have diverged. This lesson uses a fast-forward; reset to replay it.');state.main=state.tracking;state.file=recipeAt(state.main);state.fileTab='working';state.fileNotice='Your working recipe now includes the online edit you downloaded.';log('Fast-forwarded main to origin/main. Your working files now include the update.','success');applyStageProgress(cmd);return}
if(/^git pull(?: --ff-only)? origin main$/.test(cmd)){if(state.branch!=='main')throw Error('Switch to main before pulling in this lesson.');if(!isAncestor(state.main,state.remote))throw Error('Cannot fast-forward: local and remote histories have diverged.');state.tracking=state.remote;state.main=state.remote;state.file=recipeAt(state.main);state.fileTab='working';state.fileNotice='Pull updated your local recipe with the accepted online version.';log('Fetched origin, then fast-forwarded local main to GitHub main.','success');if(lesson===3&&lessons[lesson].steps[step]?.[2]==='team-pull')advance();else if(lesson===2&&lessons[lesson].steps[step]?.[2]==='git merge origin/main')advance();else render();return}
if(/^git push(?: -u)? origin (main|feature)$/.test(cmd)){if(!state.remoteConfigured)throw Error('Connect the empty GitHub repository with git remote add origin <url> first.');const b=cmd.split(' ').at(-1);if(!state[b])throw Error(`Branch ${b} does not exist.`);if(b==='main'){if(state.remote&&!isAncestor(state.remote,state.main))throw Error('Push rejected: fetch and integrate the remote changes first.');state.remote=state.main;state.tracking=state.main}log(`Published ${b} to GitHub. Your local branch stays in place.`,'success');applyStageProgress('push');return}
if(cmd==='git revert HEAD'){if(state.working||state.staged)throw Error('Commit current changes before reverting.');if(state.reverted)throw Error('The mistake is already reverted in this lesson.');if(lesson!==5)throw Error('Open Undo & recovery to practice reverting a published mistake.');state.commitContent=classicRecipe;addCommit('Revert "Accidentally remove flour"');state.file=recipeAt(state[state.branch]);state.fileNotice='The flour line is restored in this new correction commit. Inspect either circle to compare saved contents.';state.reverted=true;log('Added an inverse commit. The flour line is restored and the original history remains.','success');applyStageProgress(cmd);return}
throw Error('That command is outside this learning sandbox. Type help for supported commands.');
}catch(e){log(e.message,'error');toast(e.message)}finally{render()}}
function isAncestor(ancestor,descendant){if(ancestor===descendant)return true;const c=state.commits.find(c=>c.id===descendant);return!!c&&(Array.isArray(c.parent)?c.parent:[c.parent]).filter(Boolean).some(p=>isAncestor(ancestor,p))}
function performAction(){if(step>=lessons[lesson].steps.length){if(recapState.finished)continueAfterLesson();else focusLessonQuiz();return}const action=lessons[lesson].steps[step][2];if(action.startsWith('git remote add origin ')&&state.remoteConfigured){log('origin is already connected from your earlier command. The connection step is complete; no files have been uploaded yet.','success');advance();return}if(action==='remote-change'){log('You: open pancakes.txt in GitHub’s editor and commit clearer mixing instructions.','command');state.commitContent=updateRecipeLine(recipeAt(state.remote),'Mix ','Whisk flour, milk, and sugar until smooth.');state.fileTab='github';state.fileNotice='You changed the mixing line online. Your computer’s recipe still has the old instruction.';addCommit('Clarify mixing instructions online','remote',state.remote,'You');log('GitHub has a new snapshot. Your local main has not changed.','success');advance();return}if(action==='open-pr'){state.pr='open';log('GitHub: opened pull request #1 · feature → main.','command');log('Maya can inspect the diff, discuss changes, and review the proposal.');advance();return}if(action==='review-pr'){state.pr='approved';state.commitContent=updateRecipeLine(recipeAt(state.remote),'Mix ','Whisk flour, milk, and sugar until smooth.');state.fileTab='github';state.fileNotice='Leo updated the mixing line on GitHub. Your local feature still contains your chocolate variation.';addCommit('Leo clarifies mixing instructions','remote',state.remote,'Leo');log('Leo pushed an independent update to GitHub main. Your feature keeps its own history.');log('Maya reviewed your diff and approved pull request #1.','success');advance();return}if(action==='merge-pr'){const id=addCommit('Merge pull request #1','remote',[state.remote,state.feature],'Maya');state.remote=id;state.pr='merged';state.branch='main';state.file=recipeAt(state.main);state.fileTab='github';state.fileNotice='GitHub’s merged recipe contains chocolate chips and clearer mixing instructions. Pull to update your computer.';log('GitHub created a merge commit. Your local main still needs to be updated.','success');advance();return}if(action==='team-pull'){execute('git pull --ff-only origin main');return}if(action==='resolve-conflict'){toast('Choose a sugar amount below the graph, then continue.');$('.conflict-editor')?.scrollIntoView({behavior:'smooth',block:'nearest'});return}execute(action)}
function resolveConflict(value){state.resolved=true;state.resolution=value;state.working='resolved';state.file=updateRecipeLine(recipeAt(state.main),'Sugar:',value);state.fileTab='working';state.fileNotice='Conflict markers are gone. The recipe now contains your chosen sugar amount; stage it next.';log(`Resolved pancakes.txt: ${value}`,'success');if(step===1)advance();else render()}
function inspectCommit(id){const c=state.commits.find(c=>c.id===id);if(!c)return;openDialog(`<div class="detail-label">COMMIT SNAPSHOT</div><h2>${escapeHTML(c.message)}</h2><p><code>${c.id}</code> · ${c.author}</p><p>Parent${Array.isArray(c.parent)?'s':''}: <code>${Array.isArray(c.parent)?c.parent.join(' + '):c.parent||'None — the first commit'}</code></p><p>${Array.isArray(c.parent)?'This merge commit joins two lines of history.':'This snapshot belongs to the repository history. Branch labels can move; the saved snapshot stays the same.'}</p><div class="commit-file"><strong>pancakes.txt · saved in this commit</strong><pre>${escapeHTML(c.content)}</pre></div><p>Click another circle to inspect that version’s actual recipe.</p>`)}
function openDialog(html){$('#detail-content').innerHTML=html;$('#detail-dialog').showModal()}
function stopTour(){playing=false;clearTimeout(timer);if($('#tour'))$('#tour').innerHTML='<span>▷</span> Play walkthrough'}
function tickTour(){if(!playing)return;if(step>=lessons[lesson].steps.length){stopTour();return}if(lesson===4&&step===1)resolveConflict('Sugar: 1.5 tablespoons');else performAction();timer=setTimeout(tickTour,2400)}
function toggleTour(){if(playing){stopTour();return}if(step>=lessons[lesson].steps.length)resetLesson();playing=true;$('#tour').innerHTML='<span>Ⅱ</span> Pause walkthrough';tickTour()}
function renderView(){renderNav();$('#introduction-view').hidden=view!=='introduction';$('.intro h1').innerHTML=view==='introduction'?'Every project has a <span>story.</span>':'Make sense of <span>Git.</span>';$('.intro>div>p').textContent=view==='introduction'?'Start with a familiar idea. Learn the Git words as you go.':'Follow the buttons. Understand the action. Then try the command.';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#lab-view').hidden=view!=='lab';$('#reference-view').hidden=view!=='reference';$('#challenge-view').hidden=view!=='challenge';$('.workspace-tabs').hidden=view!=='lab';$('#tour').hidden=view!=='lab';$('#breadcrumb').textContent=view==='introduction'?'Introduction':view==='lab'?'Learning lab':view==='reference'?'Command reference':'Practice challenges';if(view==='introduction')renderIntroduction();if(view==='reference')renderReference();if(view==='challenge')renderChallenges();}
const commands=[['git remote add origin <url>','Give an existing remote repository the nickname origin.','Create an empty GitHub repository first, then use its URL. This does not upload files.',2],['git init -b main','Turn a folder into a Git repository; name the first branch main.','Run once when starting a new local project.',0],['git clone <url>','Download a repository and its history.','Creates a local copy with origin configured.',3],['git status','Inspect your branch, staged changes, and unstaged changes.','A useful first step whenever you feel lost.',0],['git diff','See the changes between working files and the staging area.','Use git diff --staged to inspect your next commit.',0],['git add <file>','Stage the file’s current content for the next snapshot.','If you edit it again, stage it again to include that edit.',0],['git commit -m "message"','Record the staged snapshot in your local history.','A commit does not publish anything to GitHub.',0],['git switch -c feature','Create a branch and start working on it.','The new branch initially points to your current commit.',1],['git switch main','Switch your working files and HEAD to main.','Save or stash changes before switching when necessary.',1],['git merge feature','Integrate feature into your current branch.','Can fast-forward, create a merge commit, or stop at conflicts.',1],['git fetch origin','Download history and refresh remote-tracking branches.','Does not integrate changes into your current branch.',2],['git pull --ff-only origin main','Fetch and update your current branch only if it can fast-forward.','Diverged branches require an explicit merge or rebase decision.',2],['git push -u origin feature','Publish feature and set its upstream tracking branch.','Push can be rejected if the remote has incompatible updates.',3],['git log --oneline','Read the commits reachable from your current branch.','Each short ID identifies a saved snapshot.',0],['git revert HEAD','Create a new commit that reverses the latest commit.','Suitable for undoing a mistake in shared history.',5],['git restore <file>','Discard unstaged edits in a tracked file.','Destructive: check git diff first. Not simulated here.',5],['git restore --staged <file>','Remove a file’s changes from the staging area.','Keeps the edits in your working directory.',0],['git stash','Temporarily save local changes for later.','Use git stash pop to reapply them; conflicts can occur.',1],['git reset --soft HEAD~1','Move the branch back one commit, keeping changes staged.','Rewrites the local branch. Avoid changing shared history.',5]];
function escapeHTML(s){return s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
function renderReference(){ $('#reference-view').innerHTML='<h2>A command for every moment.</h2><input class="reference-search" id="reference-search" placeholder="Search commands or what you want to do…" aria-label="Search command reference"><div class="reference-grid" id="reference-grid"></div>';filterReference('');$('#reference-search').addEventListener('input',e=>filterReference(e.target.value))}
function filterReference(q){const matches=commands.filter(c=>c.join(' ').toLowerCase().includes(q.toLowerCase()));$('#reference-grid').innerHTML=matches.length?matches.map(c=>`<article class="reference-card"><code>${escapeHTML(c[0])}</code><p>${c[1]}</p><small>${c[2]}</small><br><button data-lesson="${c[3]}">Explore this lesson</button></article>`).join(''):'<p>No matching commands. Try “stage”, “branch”, or “undo”.</p>'}
const quizzes=[{name:'Which recipe version gets saved?',tag:'01 · FUNDAMENTALS',desc:'You edit the recipe again after staging it. Which recipe content will the next commit save?',answers:['The version you staged.','Every edit in the working directory.','The current version on GitHub.'],correct:0,why:'git add captures the content at that moment. Later edits stay unstaged until you add them again.',lesson:0},{name:'Fetch or pull?',tag:'02 · REMOTES',desc:'You edited your own recipe on GitHub and want to inspect that update before changing your computer’s copy. What do you run?',answers:['git pull origin main','git fetch origin','git push origin main'],correct:1,why:'Fetch downloads the remote history and updates origin/main. Your working files and local main stay in place.',lesson:2},{name:'Undo without surprises',tag:'03 · SOLO RECOVERY',desc:'A recipe mistake is already saved on your GitHub repository. How do you undo it while keeping the earlier versions?',answers:['Delete the repository.','git reset --hard HEAD~1 and force push','git revert HEAD'],correct:2,why:'Revert records the inverse change as a new commit. Push the correction to update your online copy while preserving the earlier history.',lesson:5}];
function renderChallenges(){ $('#challenge-view').innerHTML='<h2>Put your mental model to the test.</h2><p class="challenge-header">Three quick scenarios. Make a prediction, get an explanation, then explore it in the lab.</p><div class="challenge-list">'+quizzes.map((q,i)=>`<article class="challenge-card"><span>${q.tag}</span><h3>${q.name}</h3><p>${q.desc}</p><button class="primary-button" data-quiz="${i}">Take the challenge <span>⚑</span></button></article>`).join('')+'</div>'}
function openQuiz(i){const q=quizzes[i];openDialog(`<div class="detail-label">${q.tag}</div><h2>${q.name}</h2><p>${q.desc}</p><div class="quiz-options">${q.answers.map((a,j)=>`<button data-answer="${j}" data-quizid="${i}">${escapeHTML(a)}</button>`).join('')}</div><div class="quiz-result" id="quiz-result" aria-live="polite"></div><button class="quiet-button" data-quizlesson="${q.lesson}">Explore in the lab</button>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.fileTab){state.fileTab=b.dataset.fileTab;renderFileWorkbench()}if(b.dataset.lesson!==undefined)selectLesson(Number(b.dataset.lesson));if(b.dataset.view){stopTour();view=b.dataset.view;renderView()}if(b.dataset.mode){selectLesson(b.dataset.mode==='team'?3:0)}if(b.dataset.command){execute(b.dataset.command);$('#command-input').focus()}if(b.dataset.resolve)resolveConflict(b.dataset.resolve);if(b.dataset.quiz!==undefined)openQuiz(Number(b.dataset.quiz));if(b.dataset.answer!==undefined){const q=quizzes[Number(b.dataset.quizid)];$('#quiz-result').textContent=(Number(b.dataset.answer)===q.correct?'Exactly. ':'Try again. ')+q.why}if(b.dataset.quizlesson){$('#detail-dialog').close();selectLesson(Number(b.dataset.quizlesson))}});
$('#graph').addEventListener('click',e=>{const n=e.target.closest('[data-commit]');if(n)inspectCommit(n.dataset.commit)});$('#graph').addEventListener('keydown',e=>{const n=e.target.closest('[data-commit]');if(n&&['Enter',' '].includes(e.key)){e.preventDefault();inspectCommit(n.dataset.commit)}});
