if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const readState=()=>({lesson:lesson+1,title:lessons[lesson].title,path:mode,pathLesson:pathPosition(),step:Math.min(step+1,lessons[lesson].steps.length),complete:step>=lessons[lesson].steps.length,initialized:state.initialized,remoteConfigured:state.remoteConfigured,commits:state.commits.length,branch:state.branch,main:state.main,feature:state.feature,remote:state.remote,staged:!!state.staged,edited:!!state.working,conflict:state.conflict,quizComplete:recapState.finished});
 const registrations=[
 {name:'read_git_lab_state',title:'Read Git lab state',description:'Read the current simulated repository and lesson progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>readState()},
 {name:'start_git_lesson',title:'Start a Git lesson',description:'Open a lesson by stable ID: 1 start locally, 2 solo branches, 3 own GitHub, 6 solo recovery; team path IDs 4 collaboration and 5 conflicts.',inputSchema:{type:'object',properties:{lesson:{type:'integer',minimum:1,maximum:6}},required:['lesson'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!Number.isInteger(input.lesson)||input.lesson<1||input.lesson>6)throw Error('Lesson must be an integer from 1 to 6.');selectLesson(input.lesson-1);return readState()}},
 {name:'advance_git_lesson',title:'Perform the next lesson action',description:'Perform the current guided sandbox action. Conflict resolution requires choosing final file content in the visible lab.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{stopTour();performAction();return readState()}}
 ];
 for(const tool of registrations){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
